+import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
+import { dirname } from "node:path";
+
+export interface LinkRecord {
+  code: string;
+  url: string;
+  createdAt: string;
+}
+
+interface StoredLinks {
+  version: 1;
+  links: LinkRecord[];
+}
+
+export class LinkRepository {
+  private readonly byCode = new Map<string, LinkRecord>();
+  private readonly codeByUrl = new Map<string, string>();
+  private writeQueue: Promise<void> = Promise.resolve();
+
+  constructor(private readonly filePath: string) {}
+
+  async initialize(): Promise<void> {
+    try {
+      const stored = JSON.parse(await readFile(this.filePath, "utf8")) as unknown;
+      if (!isStoredLinks(stored)) {
+        throw new Error(`Invalid link store format at ${this.filePath}`);
+      }
+      for (const link of stored.links) {
+        this.byCode.set(link.code, link);
+        this.codeByUrl.set(link.url, link.code);
+      }
+    } catch (error) {
+      if (isNodeError(error) && error.code === "ENOENT") {
+        await mkdir(dirname(this.filePath), { recursive: true });
+        return;
+      }
+      throw error;
+    }
+  }
+
+  findByCode(code: string): LinkRecord | undefined {
+    return this.byCode.get(code);
+  }
+
+  findByUrl(url: string): LinkRecord | undefined {
+    const code = this.codeByUrl.get(url);
+    return code === undefined ? undefined : this.byCode.get(code);
+  }
+
+  async insert(link: LinkRecord): Promise<boolean> {
+    const operation = this.writeQueue.then(async () => {
+      if (this.byCode.has(link.code)) {
+        return false;
+      }
+      this.byCode.set(link.code, link);
+      this.codeByUrl.set(link.url, link.code);
+      try {
+        await this.persist();
+      } catch (error) {
+        this.byCode.delete(link.code);
+        this.codeByUrl.delete(link.url);
+        throw error;
+      }
+      return true;
+    });
+    this.writeQueue = operation.then(
+      () => undefined,
+      () => undefined,
+    );
+    return operation;
+  }
+
+  private async persist(): Promise<void> {
+    const temporaryPath = `${this.filePath}.${process.pid}.tmp`;
+    const data: StoredLinks = {
+      version: 1,
+      links: [...this.byCode.values()],
+    };
+    await writeFile(temporaryPath, `${JSON.stringify(data, null, 2)}\n`, {
+      encoding: "utf8",
+      mode: 0o600,
+    });
+    await rename(temporaryPath, this.filePath);
+  }
+}
+
+function isStoredLinks(value: unknown): value is StoredLinks {
+  if (typeof value !== "object" || value === null) return false;
+  const candidate = value as { version?: unknown; links?: unknown };
+  return (
+    candidate.version === 1 &&
+    Array.isArray(candidate.links) &&
+    candidate.links.every(isLinkRecord)
+  );
+}
+
+function isLinkRecord(value: unknown): value is LinkRecord {
+  if (typeof value !== "object" || value === null) return false;
+  const link = value as Partial<LinkRecord>;
+  return (
+    typeof link.code === "string" &&
+    typeof link.url === "string" &&
+    typeof link.createdAt === "string"
+  );
+}
+
+function isNodeError(error: unknown): error is NodeJS.ErrnoException {
+  return error instanceof Error && "code" in error;
+}
