+import { randomBytes } from "node:crypto";
+import { AppError } from "./errors.js";
+import type { LinkRecord, LinkRepository } from "./link-repository.js";
+
+const CODE_PATTERN = /^[A-Za-z0-9_-]{6,32}$/;
+const MAX_URL_LENGTH = 2048;
+const MAX_CODE_ATTEMPTS = 10;
+
+export interface CreateLinkResult {
+  link: LinkRecord;
+  created: boolean;
+}
+
+export type CodeGenerator = () => string;
+
+export class LinkService {
+  constructor(
+    private readonly repository: LinkRepository,
+    private readonly generateCode: CodeGenerator = defaultCodeGenerator,
+  ) {}
+
+  async create(rawUrl: unknown): Promise<CreateLinkResult> {
+    const url = normalizeUrl(rawUrl);
+    const existing = this.repository.findByUrl(url);
+    if (existing !== undefined) {
+      return { link: existing, created: false };
+    }
+
+    for (let attempt = 0; attempt < MAX_CODE_ATTEMPTS; attempt += 1) {
+      const code = this.generateCode();
+      if (!CODE_PATTERN.test(code)) {
+        throw new Error("Code generator produced an invalid code");
+      }
+      const link: LinkRecord = {
+        code,
+        url,
+        createdAt: new Date().toISOString(),
+      };
+      if (await this.repository.insert(link)) {
+        return { link, created: true };
+      }
+    }
+    throw new Error("Unable to allocate a unique short code");
+  }
+
+  resolve(rawCode: string): LinkRecord {
+    if (!CODE_PATTERN.test(rawCode)) {
+      throw new AppError(
+        400,
+        "INVALID_CODE",
+        "Short code must be 6-32 URL-safe characters",
+      );
+    }
+    const link = this.repository.findByCode(rawCode);
+    if (link === undefined) {
+      throw new AppError(404, "LINK_NOT_FOUND", "Short link was not found");
+    }
+    return link;
+  }
+}
+
+export function normalizeUrl(rawUrl: unknown): string {
+  if (typeof rawUrl !== "string" || rawUrl.length === 0) {
+    throw new AppError(400, "INVALID_URL", "url must be a non-empty string");
+  }
+  if (rawUrl.length > MAX_URL_LENGTH) {
+    throw new AppError(
+      400,
+      "INVALID_URL",
+      `url must not exceed ${MAX_URL_LENGTH} characters`,
+    );
+  }
+  let url: URL;
+  try {
+    url = new URL(rawUrl);
+  } catch {
+    throw new AppError(400, "INVALID_URL", "url must be a valid absolute URL");
+  }
+  if (url.protocol !== "http:" && url.protocol !== "https:") {
+    throw new AppError(400, "INVALID_URL", "url must use http or https");
+  }
+  if (url.username !== "" || url.password !== "") {
+    throw new AppError(400, "INVALID_URL", "url must not contain credentials");
+  }
+  return url.href;
+}
+
+function defaultCodeGenerator(): string {
+  return randomBytes(6).toString("base64url");
+}
*** Add File: src/app.ts
+import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
+import { AppError } from "./errors.js";
+import type { LinkRecord } from "./link-repository.js";
+import type { LinkService } from "./link-service.js";
+
+const MAX_BODY_BYTES = 4_096;
+
+export interface AppOptions {
+  publicBaseUrl: string;
+}
+
+export function createApp(service: LinkService, options: AppOptions) {
+  const baseUrl = options.publicBaseUrl.replace(/\/+$/, "");
+
+  return createServer(async (request, response) => {
+    try {
+      await route(request, response, service, baseUrl);
+    } catch (error) {
+      handleError(response, error);
+    }
+  });
+}
+
+async function route(
+  request: IncomingMessage,
+  response: ServerResponse,
+  service: LinkService,
+  baseUrl: string,
+): Promise<void> {
+  const url = new URL(request.url ?? "/", "http://localhost");
+
+  if (url.pathname === "/health") {
+    ensureMethod(request, "GET");
+    sendJson(response, 200, { status: "ok" });
+    return;
+  }
+
+  if (url.pathname === "/api/links") {
+    ensureMethod(request, "POST");
+    const body = await readJsonBody(request);
+    const result = await service.create(
+      typeof body === "object" && body !== null
+        ? (body as Record<string, unknown>).url
+        : undefined,
+    );
+    sendJson(response, result.created ? 201 : 200, serialize(result.link, baseUrl));
+    return;
+  }
+
+  const apiMatch = /^\/api\/links\/([^/]+)$/.exec(url.pathname);
+  if (apiMatch?.[1] !== undefined) {
+    ensureMethod(request, "GET");
+    sendJson(response, 200, serialize(service.resolve(apiMatch[1]), baseUrl));
+    return;
+  }
+
+  const redirectMatch = /^\/([^/]+)$/.exec(url.pathname);
+  if (redirectMatch?.[1] !== undefined) {
+    ensureMethod(request, "GET");
+    const link = service.resolve(redirectMatch[1]);
+    response.writeHead(302, {
+      location: link.url,
+      "cache-control": "no-store",
+      "content-length": "0",
+    });
+    response.end();
+    return;
+  }
+
+  throw new AppError(404, "LINK_NOT_FOUND", "Route was not found");
+}
+
+function ensureMethod(request: IncomingMessage, expected: string): void {
+  if (request.method !== expected) {
+    throw new AppError(
+      405,
+      "METHOD_NOT_ALLOWED",
+      `Method ${request.method ?? "UNKNOWN"} is not allowed`,
+    );
+  }
+}
+
+async function readJsonBody(request: IncomingMessage): Promise<unknown> {
+  const chunks: Buffer[] = [];
+  let size = 0;
+  for await (const chunk of request) {
+    const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk as Uint8Array);
+    size += buffer.length;
+    if (size > MAX_BODY_BYTES) {
+      throw new AppError(413, "PAYLOAD_TOO_LARGE", "Request body is too large");
+    }
+    chunks.push(buffer);
+  }
+  try {
+    return JSON.parse(Buffer.concat(chunks).toString("utf8")) as unknown;
+  } catch {
+    throw new AppError(400, "INVALID_JSON", "Request body must be valid JSON");
+  }
+}
+
+function serialize(link: LinkRecord, baseUrl: string) {
+  return {
+    code: link.code,
+    url: link.url,
+    shortUrl: `${baseUrl}/${link.code}`,
+    createdAt: link.createdAt,
+  };
+}
+
+function sendJson(response: ServerResponse, status: number, body: unknown): void {
+  const payload = JSON.stringify(body);
+  response.writeHead(status, {
+    "content-type": "application/json; charset=utf-8",
+    "content-length": Buffer.byteLength(payload),
+  });
+  response.end(payload);
+}
+
+function handleError(response: ServerResponse, error: unknown): void {
+  if (response.headersSent) {
+    response.destroy(error instanceof Error ? error : undefined);
+    return;
+  }
+  if (error instanceof AppError) {
+    sendJson(response, error.status, {
+      error: { code: error.code, message: error.message },
+    });
+    return;
+  }
+  console.error(error);
+  sendJson(response, 500, {
+    error: { code: "INTERNAL_ERROR", message: "An unexpected error occurred" },
+  });
+}
