+import { resolve } from "node:path";
+import { createApp } from "./app.js";
+import { LinkRepository } from "./link-repository.js";
+import { LinkService } from "./link-service.js";
+
+const port = parsePort(process.env.PORT);
+const publicBaseUrl = process.env.PUBLIC_BASE_URL ?? `http://localhost:${port}`;
+const dataFile = resolve(process.env.DATA_FILE ?? "data/links.json");
+
+const repository = new LinkRepository(dataFile);
+await repository.initialize();
+
+const server = createApp(new LinkService(repository), { publicBaseUrl });
+server.listen(port, () => {
+  console.log(`URL shortener listening on ${publicBaseUrl}`);
+});
+
+function parsePort(value: string | undefined): number {
+  if (value === undefined) return 3000;
+  const parsed = Number(value);
+  if (!Number.isInteger(parsed) || parsed < 1 || parsed > 65_535) {
+    throw new Error("PORT must be an integer between 1 and 65535");
+  }
+  return parsed;
+}
