+export interface ShortenedLink {
+  shortUrl: string
+}
+
+interface ApiError {
+  message?: string
+}
+
+const API_BASE_URL = import.meta.env.VITE_API_URL?.replace(/\/$/, '') ?? ''
+
+export async function shortenUrl(url: string): Promise<ShortenedLink> {
+  const response = await fetch(`${API_BASE_URL}/api/shorten`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ url }),
+  })
+
+  if (!response.ok) {
+    let error: ApiError = {}
+    try {
+      error = (await response.json()) as ApiError
+    } catch {
+      // The fallback below preserves a useful message for non-JSON server responses.
+    }
+    throw new Error(error.message || 'We could not shorten that link. Please try again.')
+  }
+
+  const result = (await response.json()) as Partial<ShortenedLink>
+  if (typeof result.shortUrl !== 'string' || result.shortUrl.length === 0) {
+    throw new Error('The server returned an invalid shortened link.')
+  }
+
+  return { shortUrl: result.shortUrl }
+}
