+import { FormEvent, useRef, useState } from 'react'
+import { shortenUrl } from './api'
+import { validateUrl } from './validation'
+
+type RequestState =
+  | { status: 'idle' }
+  | { status: 'loading' }
+  | { status: 'success'; shortUrl: string }
+  | { status: 'error'; message: string }
+
+export function App() {
+  const [url, setUrl] = useState('')
+  const [validationError, setValidationError] = useState<string | null>(null)
+  const [request, setRequest] = useState<RequestState>({ status: 'idle' })
+  const [copied, setCopied] = useState(false)
+  const inputRef = useRef<HTMLInputElement>(null)
+
+  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
+    event.preventDefault()
+    const error = validateUrl(url)
+    setValidationError(error)
+    setCopied(false)
+
+    if (error) {
+      inputRef.current?.focus()
+      return
+    }
+
+    setRequest({ status: 'loading' })
+    try {
+      const result = await shortenUrl(url.trim())
+      setRequest({ status: 'success', shortUrl: result.shortUrl })
+    } catch (error) {
+      setRequest({
+        status: 'error',
+        message: error instanceof Error ? error.message : 'An unexpected error occurred.',
+      })
+    }
+  }
+
+  async function handleCopy() {
+    if (request.status !== 'success') return
+    try {
+      await navigator.clipboard.writeText(request.shortUrl)
+      setCopied(true)
+    } catch {
+      setRequest({ status: 'error', message: 'Could not copy the link. Please copy it manually.' })
+    }
+  }
+
+  return (
+    <div className="app-shell">
+      <header className="site-header">
+        <a className="brand" href="/" aria-label="Shortly home">
+          shortly<span aria-hidden="true">.</span>
+        </a>
